//! Main-thread file selection and I/O, with Rust-only handles for other workers.
//!
//! [`save_file`] saves generated bytes from the UI thread.
//!
//! Poll [`FileService::run`] alongside the application's main-thread lifecycle.
//! File selection runs there too. [`File`] is `Clone + Send + Sync` and uses Rust
//! channels. [`Directory`] provides the same worker access for directory browsing.
//! Neither handle contains a browser object or platform path. Browser directory
//! selection requires HTTPS (or localhost) and user activation when first polled.
//!
//! Native disk operations use a blocking I/O pool. Browser promises stay on the
//! service's thread. The caller owns application scheduling and DOS/VFS mounting.
//!
//! ```no_run
//! use relocade_file_picker::FileService;
//! # async fn example() -> std::io::Result<()> {
//! let files = FileService::new();
//! let work = async {
//!     if let Some(file) = files.pick_file().await? {
//!         // This handle may also be sent to the existing execution worker.
//!         let metadata = file.metadata().await?;
//!         let mut header = [0; 32];
//!         let count = file.read_at(&mut header, 0).await?;
//!     }
//!     Ok::<_, std::io::Error>(())
//! };
//! let (result, ()) = futures_lite::future::zip(async {
//!     let result = work.await;
//!     files.close();
//!     result
//! }, files.run()).await;
//! result
//! # }
//! ```
#![forbid(unsafe_code)]

mod directory;
mod file;
mod metadata;
mod service;
pub use directory::{DirEntry, Directory};
pub use file::File;
pub use metadata::{EntryKind, Metadata};
pub use service::FileService;

#[cfg(not(target_arch = "wasm32"))]
#[path = "platform/native.rs"]
mod platform;
#[cfg(target_arch = "wasm32")]
#[path = "platform/web.rs"]
mod platform;

/// Saves owned bytes under a suggested filename. Call from the UI thread.
///
/// On desktop, Save As returns `None` if the picker returns no destination.
/// Otherwise the file is replaced after all bytes have been written in the
/// destination directory. On the web, `Some(())` means a download was requested.
/// Browser settings determine the destination and whether to prompt the user.
pub async fn save_file(suggested_name: &str, contents: Vec<u8>) -> std::io::Result<Option<()>> {
    validate_name(suggested_name)?;
    platform::save_file(suggested_name, contents).await
}

fn validate_name(name: &str) -> std::io::Result<()> {
    if matches!(name, "" | "." | "..") || name.contains(['/', '\\', '\0', ':']) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "expected one filename or directory name",
        ));
    }
    Ok(())
}

/// Access enforced by the service for a directory or file.
/// Read/write access permits requests; OS or browser permissions can still deny them.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Access {
    ReadOnly,
    ReadWrite,
}

impl Access {
    pub(crate) fn require(self, requested: Self) -> std::io::Result<()> {
        if self == Self::ReadOnly && requested == Self::ReadWrite {
            Err(std::io::Error::new(
                std::io::ErrorKind::PermissionDenied,
                "read-only access",
            ))
        } else {
            Ok(())
        }
    }
}
